    clauses = inst["clauses"]; m = inst["num_vars"]
    # simple backtracking with unit propagation
    def rec(clauses, assign):
        # unit propagate
        while True:
            unit = None
            for cl in clauses:
                unassigned = []
                sat = False
                for lit in cl:
                    v = abs(lit); val = assign.get(v)
                    if val is None:
                        unassigned.append(lit)
                    elif (lit > 0) == val:
                        sat = True; break
                if sat: continue
                if not unassigned:
                    return False
